#!/bin/bash
# Download all datasets/models needed by this reproduction.
#
# Estimated download size: 0 bytes.
# Estimated disk usage after extraction: 0 bytes.
#
# The gym is analytic: instances, exact intensities and ground truth are
# generated by eval/ at evaluation time, so no external assets are needed.

set -euo pipefail

REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
cd "$REPO_ROOT"
mkdir -p data/downloads
echo "No external downloads: every problem instance is generated analytically by the evaluators."
